mapper.select:
select id, title, week_number, sessions_per_week, cycle_days, description, subtitle, cover_image, detail_image, home_image, level, training_scene, session_minutes, benefit_one, benefit_two, benefit_three from training_plans where active = true
and id = #{planId}
order by sort_order, id limit 1

mapper.update:
update user_plan_selections
set plan_id = #{planId}, selected_at = current_timestamp
where user_id = #{userId}
